def configure_telegram_notifications(bot, username=None):
    """Enable best-effort Telegram notifications for requests created on the web."""
    global _telegram_bot, _telegram_loop, _telegram_username
    _telegram_bot = bot
    _telegram_loop = asyncio.get_running_loop()
    _telegram_username = username

def notify_telegram_user(user_id, text, reply_markup=None):
    if _telegram_bot is None or _telegram_loop is None:
        return
    try:
        future = asyncio.run_coroutine_threadsafe(
            _telegram_bot.send_message(user_id, text, reply_markup=reply_markup), _telegram_loop
        )
    except RuntimeError:
        logging.warning("Telegram notification could not be scheduled")
        return

    def report_failure(result):
        try:
            result.result()
        except Exception:
            logging.warning("Telegram notification failed")

    future.add_done_callback(report_failure)

def now(): return dt.datetime.now(dt.timezone.utc)
def ph(password, salt=None):
    """Use a memory-hard password hash for new credentials."""
    salt = salt or secrets.token_hex(16)
    digest = hashlib.scrypt(password.encode("utf-8"), salt=salt.encode("utf-8"), n=2**14, r=8, p=1, dklen=32)
    return f"scrypt$16384$8$1${salt}${digest.hex()}"
def pv(password, stored):
    try:
        parts = stored.split("$")
        if parts[0] == "scrypt" and len(parts) == 6:
            _, n, r, p, salt, digest = parts
            actual = hashlib.scrypt(password.encode("utf-8"), salt=salt.encode("utf-8"), n=int(n), r=int(r), p=int(p), dklen=32).hex()
            return hmac.compare_digest(actual, digest)
        # Existing accounts keep working and are transparently upgraded at login.
        salt, digest = stored.split("$", 1)
        actual = hashlib.pbkdf2_hmac("sha256", password.encode(), salt.encode(), 180000).hex()
        return hmac.compare_digest(actual, digest)
    except Exception: return False
def password_needs_upgrade(stored):
    try:
        scheme, n, r, p, _salt, _digest = stored.split("$")
        return scheme != "scrypt" or int(n) < 2**14 or int(r) < 8 or int(p) < 1
    except (AttributeError, TypeError, ValueError):
        return True

def password_error(password):
    if not 6 <= len(password) <= 256:
        return "Пароль должен быть от 6 до 256 символов."
    if not re.search(r"[a-z]", password) or not re.search(r"[A-Z]", password) or not re.search(r"\d", password):
        return "В пароле нужны строчная и заглавная латинские буквы, а также цифра."
    return None

def email_delivery_configured():
    return bool(SMTP_HOST and SMTP_USERNAME and SMTP_PASSWORD and SMTP_FROM)

def _send_email(address, subject, body):
    """Send a transactional mail using either STARTTLS or implicit TLS."""
    if not email_delivery_configured():
        return False
    message = EmailMessage()
    message["Subject"] = subject
    message["From"] = SMTP_FROM
    message["To"] = address
    message.set_content(body)
    for attempt in range(2):
        phase = "connect"
        try:
            context = ssl.create_default_context()
            client = (smtplib.SMTP_SSL(SMTP_HOST, SMTP_PORT, timeout=SMTP_TIMEOUT_SECONDS, context=context)
                      if SMTP_USE_SSL else smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=SMTP_TIMEOUT_SECONDS))
            with client:
                phase = "tls"
                client.ehlo()
                if SMTP_USE_TLS and not SMTP_USE_SSL:
                    client.starttls(context=context)
                    client.ehlo()
                phase = "login"
                client.login(SMTP_USERNAME, SMTP_PASSWORD)
                phase = "send"
                client.send_message(message)
                # SMTP acceptance is definitive even if QUIT subsequently fails.
                phase = "accepted"
            return True
        except Exception as error:
            if phase == "accepted":
                return True
            transient = isinstance(error, (TimeoutError, ConnectionError, smtplib.SMTPServerDisconnected))
            if attempt == 0 and phase in {"connect", "tls", "login"} and transient:
                continue
            # Never retry DATA: the server may already have accepted the message.
            # Do not log recipients, codes or provider credentials.
            logging.error("Transactional email delivery failed: phase=%s type=%s smtp_code=%s",
                          phase, type(error).__name__, getattr(error, "smtp_code", None))
            return False

def send_email_verification_code(address, code):
    return _send_email(
        address,
        "Код подтверждения H-Point",
        "Ваш код подтверждения H-Point: " + code + "\n\n"
        + f"Код действует {max(1, EMAIL_VERIFICATION_TTL_SECONDS // 60)} минут. Никому его не сообщайте.",
    )

