def sms_delivery_configured():
    return bool(BREVO_API_KEY and SMS_SENDER)

def send_phone_verification_code(phone, code):
    """Deliver an SMS through Brevo only when an API key was configured."""
    if not sms_delivery_configured():
        return False
    payload = json.dumps({
        "type": "transactional", "unicodeEnabled": True,
        "sender": SMS_SENDER, "recipient": phone.lstrip("+"),
        "content": f"H-Point: код подтверждения телефона {code}. Никому его не сообщайте.",
    }).encode("utf-8")
    req = urlrequest.Request(
        "https://api.brevo.com/v3/transactionalSMS", data=payload, method="POST",
        headers={"api-key": BREVO_API_KEY, "Content-Type": "application/json", "Accept": "application/json"},
    )
    try:
        with urlrequest.urlopen(req, timeout=SMTP_TIMEOUT_SECONDS) as response:
            return 200 <= response.status < 300
    except (urlerror.URLError, TimeoutError, ValueError):
        logging.exception("Phone verification SMS delivery failed")
        return False

def cookie_value(h, name):
    c=h.headers.get("Cookie","")
    return next((x.strip().split("=",1)[1] for x in c.split(";") if x.strip().startswith(name+"=")),None)

def session_token_hash(token):
    return hashlib.sha256(token.encode("utf-8")).hexdigest()

def revoke_session(token):
    """Remove a current hashed token and a short-lived legacy raw token."""
    if token:
        db.execute("DELETE FROM sessions WHERE token IN (?,?)", (session_token_hash(token), token))

def get_sess(h, allow_unverified=False):
    t=cookie_value(h,"hpoint_session")
    if not t: return None
    token_hash=session_token_hash(t)
    r=db.execute("SELECT * FROM sessions WHERE token=? AND expires_at>?",(token_hash,now().isoformat())).fetchone()
    if not r:
        # Sessions created before token-at-rest hardening keep working until
        # expiry, then are upgraded on first legitimate use.
        r=db.execute("SELECT * FROM sessions WHERE token=? AND expires_at>?",(t,now().isoformat())).fetchone()
        if r:
            db.execute("UPDATE sessions SET token=? WHERE token=?",(token_hash,t))
    user = get_user(r["user_id"]) if r else None
    return user if user and (allow_unverified or account_is_verified(user)) else None

def new_sess(uid, device_id=None):
    t=secrets.token_urlsafe(32)
    e=(now()+dt.timedelta(seconds=SESSION_TTL)).isoformat()
    db.execute("DELETE FROM sessions WHERE expires_at<=?", (now().isoformat(),))
    db.execute("INSERT INTO sessions(token,user_id,expires_at,device_id,auth_method) VALUES(?,?,?,?,'email')",(session_token_hash(t),uid,e,device_id))
    database.touch_user_activity(uid)
    return t

def session_cookie(value, max_age):
    secure = "; Secure" if SESSION_COOKIE_SECURE else ""
    return f"hpoint_session={value}; HttpOnly; SameSite=Lax; Path=/; Max-Age={max_age}{secure}"

def device_cookie(value):
    secure = "; Secure" if SESSION_COOKIE_SECURE else ""
    return f"hpoint_device={value}; HttpOnly; SameSite=Lax; Path=/; Max-Age={SESSION_TTL}{secure}"

def session_headers(h, uid):
    device = cookie_value(h, "hpoint_device") or secrets.token_urlsafe(24)
    return {"Set-Cookie": [session_cookie(new_sess(uid, device), SESSION_TTL), device_cookie(device), verification_cookie("", 0)]}

def verification_cookie(value, max_age):
    secure = "; Secure" if SESSION_COOKIE_SECURE else ""
    return f"hpoint_verification={value}; HttpOnly; SameSite=Lax; Path=/; Max-Age={max_age}{secure}"

def verification_token_hash(token):
    # Domain separation prevents using a pending token as a normal login session.
    return session_token_hash("email-verification:" + token)

def email_verification_user(h):
    token = cookie_value(h, "hpoint_verification")
    row = db.execute("SELECT user_id FROM sessions WHERE token=? AND expires_at>?",
                     (verification_token_hash(token), now().isoformat())).fetchone() if token else None
    user = get_user(row["user_id"]) if row else get_sess(h, allow_unverified=True)
    if not user:
        reply(h, {"ok": False, "error": "Войдите по email и паролю, чтобы запросить новый код."}, 401)
        return None
    if user["is_blocked"]:
        reply(h, {"ok": False, "error": "account_blocked"}, 403)
        return None
    return user

def email_challenge(h, user, pending=True):
    if not email_delivery_configured():
        return reply(h, {"ok": False, "error": "Отправка писем временно недоступна. Попробуйте позже или повторите попытку позже или обратитесь в поддержку."}, 503)
    uid = user["user_id"]
    if not database.reserve_auth_attempts(("email_resend", str(uid), 3)):
        return reply(h, {"ok": False, "error": "Слишком много кодов. Повторите через 15 минут."}, 429)
    code = database.create_email_verification_code(uid)
    if not send_email_verification_code(user["email"], code):
        db.execute("DELETE FROM email_verification_codes WHERE user_id=? AND code_hash=?",
                   (uid, hashlib.sha256(code.encode()).hexdigest()))
        return reply(h, {"ok": False, "error": "Не удалось отправить код. Вход не выполнен. Повторите попытку или повторите попытку позже или обратитесь в поддержку."}, 503)
    headers = None
    if pending:
        previous = cookie_value(h, "hpoint_verification")
        if previous:
            db.execute("DELETE FROM sessions WHERE token=?", (verification_token_hash(previous),))
        token = secrets.token_urlsafe(32)
        expires = (now() + dt.timedelta(seconds=EMAIL_VERIFICATION_TTL_SECONDS)).isoformat()
        db.execute("DELETE FROM sessions WHERE expires_at<=?", (now().isoformat(),))
        db.execute("INSERT INTO sessions(token,user_id,expires_at) VALUES(?,?,?)",
                   (verification_token_hash(token), uid, expires))
        headers = {"Set-Cookie": [verification_cookie(token, EMAIL_VERIFICATION_TTL_SECONDS), session_cookie("", 0)]}
    return reply(h, {"ok": True, "verification_required": pending, "email_verification_sent": True, "sent": True}, headers=headers)

MAX_JSON_BODY = 20_000
EVENT_JSON_BODY = EVENT_IMAGE_MAX_BYTES * 2 + 10_000

def read(h, max_body=MAX_JSON_BODY):
    try: length = int(h.headers.get("Content-Length", "0"))
    except ValueError: raise ValueError("Некорректный размер запроса")
    if length < 0 or length > max_body: raise ValueError("Слишком большой запрос")
    return json.loads(h.rfile.read(length) or b"{}")

GEOCODE_CACHE = {}
GEOCODE_LOCK = threading.Lock()
GEOCODE_LAST_REQUEST_AT = 0.0

def geocode_address(query):
    """Resolve an explicitly submitted address without retaining it in the database."""
    global GEOCODE_LAST_REQUEST_AT
    value = " ".join(str(query or "").split())
    if not 4 <= len(value) <= 180:
        raise ValueError("Укажите адрес от 4 до 180 символов.")
    cache_key = value.casefold()
    moment = time.monotonic()
    with GEOCODE_LOCK:
        cached = GEOCODE_CACHE.get(cache_key)
        if cached and moment - cached[0] < 6 * 60 * 60:
            return cached[1]
        if moment - GEOCODE_LAST_REQUEST_AT < 1.05:
            raise RuntimeError("Подождите секунду и повторите поиск адреса.")
        GEOCODE_LAST_REQUEST_AT = moment
    request_url = "https://photon.komoot.io/api/?" + urlencode({"q": value, "limit": 1})
    request_obj = urlrequest.Request(request_url, headers={
        "User-Agent": "H-Point/1.0 (+https://gethpoint.ru)", "Accept": "application/json",
    })
    try:
        with urlrequest.urlopen(request_obj, timeout=8) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except (urlerror.URLError, TimeoutError, ValueError, json.JSONDecodeError) as exc:
        logging.warning("Fallback geocoding is unavailable: %s", type(exc).__name__)
        raise RuntimeError("Поиск адреса временно недоступен. Поставьте точку на карте.") from exc
    rows = payload.get("features") if isinstance(payload, dict) else None
    if not isinstance(rows, list) or not rows:
        raise ValueError("Адрес не найден. Уточните город, улицу и номер дома.")
    try:
        lon, lat = rows[0]["geometry"]["coordinates"][:2]
        point = {"lat": float(lat), "lon": float(lon)}
    except (KeyError, TypeError, ValueError, IndexError) as exc:
        raise RuntimeError("Не удалось определить координаты адреса.") from exc
    if not (-90 <= point["lat"] <= 90 and -180 <= point["lon"] <= 180):
        raise RuntimeError("Сервис вернул некорректные координаты.")
    with GEOCODE_LOCK:
        GEOCODE_CACHE[cache_key] = (time.monotonic(), point)
        if len(GEOCODE_CACHE) > 256:
            oldest = min(GEOCODE_CACHE, key=lambda key: GEOCODE_CACHE[key][0])
            GEOCODE_CACHE.pop(oldest, None)
    return point

def event_image_data(value):
    raw=str(value or "").strip()
    if not raw:return ""
    match=re.fullmatch(r"data:(image/(?:jpeg|png|webp));base64,([A-Za-z0-9+/=]+)",raw)
    if not match:raise ValueError("Фото должно быть PNG, JPEG или WebP.")
    try:payload=base64.b64decode(match.group(2),validate=True)
    except (binascii.Error,ValueError):raise ValueError("Не удалось прочитать фото.")
    if not payload or len(payload)>EVENT_IMAGE_MAX_BYTES:raise ValueError("Фото должно быть не больше 800 КБ.")
    signatures={"image/jpeg":b"\xff\xd8\xff","image/png":b"\x89PNG\r\n\x1a\n","image/webp":b"RIFF"}
    if not payload.startswith(signatures[match.group(1)]):raise ValueError("Формат фото не совпадает с файлом.")
    return f"data:{match.group(1)};base64,"+base64.b64encode(payload).decode("ascii")

def reply(h,d,status=200,headers=None):
    b=json.dumps(d,ensure_ascii=False).encode()
    h.send_response(status); h.send_header("Content-Type","application/json;charset=utf-8"); h.send_header("Cache-Control","no-store"); h.send_header("X-Content-Type-Options","nosniff"); h.send_header("Referrer-Policy","same-origin"); h.send_header("Content-Length",str(len(b)))
    for k,v in (headers or {}).items():
        for value in (v if k.lower()=="set-cookie" and isinstance(v,(list,tuple)) else (v,)):
            h.send_header(k,value)
    try:
        h.end_headers(); h.wfile.write(b)
    except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
        # Mobile navigation may close an already processed request's socket.
        # Its committed result must not be retried or reported as HTTP 500.
        return

def auth(h):
    u=get_sess(h)
    if not u:
        reply(h,{"ok":False,"error":"auth_required"},401); return None
    if u["is_blocked"]:
        reply(h,{"ok":False,"error":"account_blocked"},403); return None
    return u

def account_is_verified(u):
    return bool(u["email"] and u["email_verified"])

def verified_community_account(h, u):
    if account_is_verified(u):
        return True
    reply(h, {"ok": False, "error": "Подтвердите email кодом из письма, прежде чем пользоваться заявками."}, 403)
    return False

def admin_auth(h):
    u = auth(h)
    if u and u["role"] != "admin":
        reply(h,{"ok":False,"error":"forbidden"},403); return None
    return u

def valid_origin(h):
    origin = h.headers.get("Origin")
    if not origin:
        # Browser fetch/XHR sends Origin for unsafe requests.  Requiring it in
        # production prevents a request with an ambient session cookie from
        # being accepted when a proxy or browser misbehaves around SameSite.
        # Keep direct, local development clients convenient.
        return APP_ENV not in {"production", "prod"}
    public = urlparse(WEB_PUBLIC_URL)
    expected = f"{public.scheme}://{public.netloc}"
    return hmac.compare_digest(origin.rstrip("/"), expected.rstrip("/"))

def client_key(h):
    if TRUST_PROXY_HEADERS:
        forwarded=h.headers.get("X-Forwarded-For", "").split(",")[0].strip()
        if forwarded:return forwarded
    return h.client_address[0]

